-- clean_lesson_titles_2026-07-29.sql
--
-- 1703 lesson titles are raw YouTube keyword soup ("#7 Examples on
-- motion under gravity with graph | Rectilinear motion | Kinematics | IIT
-- advanced |JEE"). Replace each with a concise editorial title. The lesson
-- list shows position numbers and course/chapter context, so numbering and
-- keyword tails carry no information there.
--
-- Non-destructive, mirroring content_quality_v10's playlist treatment:
-- videos.source_title preserves every original YouTube title (new column,
-- backfilled first). The update refuses rows whose title no longer matches
-- source_title (already edited by someone). Idempotent: a re-run updates
-- nothing and the final-state verification still passes.
-- Titles drafted per-course, adversarially reviewed, and mechanically
-- validated against the repo's titleQuality rules before this file was
-- generated. Import/refresh scripts never overwrite videos.title.

begin;

alter table public.videos add column if not exists source_title text;

update public.videos
   set source_title = title
 where source_title is null;

update public.videos v
   set title = n.new_title
